test('Should use all dns entries (dual stack)', async t => {
  t = tspl(t, { plan: 16 })

  let counter = 0
  let lookupCounter = 0
  const server = createServer({ joinDuplicateHeaders: true })
  const requestOptions = {
    method: 'GET',
    path: '/',
    headers: {
      'content-type': 'application/json'
    }
  }

  server.on('request', (req, res) => {
    res.writeHead(200, { 'content-type': 'text/plain' })
    res.end('hello world!')
  })

  server.listen(0)

  await once(server, 'listening')

  const client = new Agent().compose([
    dispatch => {
      return (opts, handler) => {
        ++counter
        const url = new URL(opts.origin)
        switch (counter) {
          case 1:
            t.equal(url.hostname, '1.1.1.1')
            break

          case 2:
            t.equal(url.hostname, '[::1]')
            break

          case 3:
            t.equal(url.hostname, '2.2.2.2')
            break

          case 4:
            t.equal(url.hostname, '[::2]')
            break

          case 5:
            t.equal(url.hostname, '1.1.1.1')
            break
          default:
            t.fail('should not reach this point')
        }

        url.hostname = '127.0.0.1'
        opts.origin = url.toString()
        return dispatch(opts, handler)
      }
    },
    dns({
      lookup (origin, opts, cb) {
        lookupCounter++
        cb(null, [
          { address: '::1', family: 6 },
          { address: '::2', family: 6 },
          { address: '1.1.1.1', family: 4 },
          { address: '2.2.2.2', family: 4 }
        ])
      }
    })
  ])

  after(async () => {
    await client.close()
    server.close()

    await once(server, 'close')
  })

  for (let i = 0; i < 5; i++) {
