test('Should keep the original hostname available on the socket for plain HTTP', async t => {
  t = tspl(t, { plan: 4 })

  const server = createServer({ joinDuplicateHeaders: true })
  server.on('request', (req, res) => {
    res.end('hello world!')
  })

  server.listen(0)
  await once(server, 'listening')

  const sockets = []
  const onClientSocket = ({ socket }) => {
    sockets.push(socket)
  }
  diagnosticsChannel.subscribe('net.client.socket', onClientSocket)

  const client = new Client(`http://localhost:${server.address().port}`).compose(dns({
    lookup: (_origin, _opts, cb) => {
      cb(null, [{ address: '127.0.0.1', family: 4, ttl: 60e3 }])
    }
  }))

  after(async () => {
    diagnosticsChannel.unsubscribe('net.client.socket', onClientSocket)
    await client.close()
    server.close()
    await once(server, 'close')
  })

  const response = await client.request({
    method: 'GET',
    path: '/'
  })

  t.equal(response.statusCode, 200)
  t.equal(await response.body.text(), 'hello world!')
  t.equal(sockets.length, 1)
  t.deepStrictEqual({
    remoteAddress: sockets[0].remoteAddress,
    host: sockets[0]._host
  }, {
    remoteAddress: '127.0.0.1',
    host: 'localhost'
  })
})

